function contextHeaders(ctx){return{"x-workspace-id":ctx.workspaceId,"x-actor-sub":ctx.actorSub,"x-authenticated":ctx.authenticated?"1":"0","x-persistence":ctx.persistence,"x-can-write":ctx.canWrite?"1":"0"}}
function contextResponse(resp,ctx){if(!ctx?.guest?.fresh)return resp;const h=new Headers(resp.headers);h.append("set-cookie",ctx.guest.cookie);return new Response(resp.body,{status:resp.status,statusText:resp.statusText,headers:h})}
async function aiQuota(env,ctx,kind){const guestLimits={interpret:8,assist:12,live_assist:20,training:4,audio:20,research:10},limit=ctx.authenticated?120:(guestLimits[kind]||10),r=await doStub(env).fetch("https://internal/ai-quota",{method:"POST",headers:{...contextHeaders(ctx),"content-type":"application/json"},body:JSON.stringify({kind,limit})});if(r.ok)return{ok:true};const x=await r.json().catch(()=>({error:"ai_rate_limited"}));return{ok:false,status:r.status,data:x}}
async function stateForContext(env,ctx,customerId){const r=await doStub(env).fetch("https://internal/state?customer="+encodeURIComponent(customerId),{headers:contextHeaders(ctx)});if(!r.ok)return{ok:false,status:r.status,data:await r.json().catch(()=>({error:"customer_state_unavailable"}))};return{ok:true,data:await r.json()}}
async function publicResearchQuery(env,input,state){const qb=await cpAI(env,{task:"dpl_public_research_query",prompt:"Create one de-identified public web research query from the operator request below. Keep only generic vendor/product/technology/best-practice concepts that are safe to send to an external search provider. Remove customer/company names, people, emails, exact internal dates, private metrics, account-specific identifiers, and confidential implementation details. Return JSON only: {needed:boolean,query:string}. Operator request: "+String(input||"").slice(0,6000),context:""});const qj=parseAiJson(qb.data?.text);return qb.data?.available&&qj?.needed!==false&&qj?.query?scrubPublicResearchQuery(qj.query,state):""}

async function currentSession(req,env){const sid=cookie(req,SESSION_COOKIE);if(!sid)return null;const stub=doStub(env);let r=await stub.fetch("https://internal/session/"+encodeURIComponent(sid));if(!r.ok)return null;let s=await r.json();let user=null;if(Number(s.expiresAt||0)>Date.now()+30000)user=await userInfo(s.accessToken).catch(()=>null);if(!user){const nt=await refreshTokens(s).catch(()=>null);if(!nt)return null;await stub.fetch("https://internal/session/"+encodeURIComponent(sid),{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify(nt)});user=await userInfo(nt.accessToken).catch(()=>null);if(!user)return null;s={...s,...nt}}if(!userAllowed(user))return null;return {sid,user,workspaceId:WORKSPACE_ID}}
